"""使用模拟模型和工具验证结构化工具调用，全程不发送网络请求。"""

import os
import unittest
from copy import deepcopy
from unittest.mock import Mock, patch

from openai.types.chat import ChatCompletionMessage

with patch.dict(os.environ, {"DASHSCOPE_API_KEY": "test-key", "DASHSCOPE_BASE_URL": "https://example.com/v1"}):
    from datawhale.section1 import first_agent as agent


def tool_message(*calls) -> ChatCompletionMessage:
    """构造 SDK 消息，calls 中每项为调用 ID、工具名和 JSON 参数。"""
    return ChatCompletionMessage(
        role="assistant",
        tool_calls=[
            {"id": call_id, "type": "function", "function": {"name": name, "arguments": args}}
            for call_id, name, args in calls
        ],
    )


class ToolCallingTests(unittest.TestCase):
    """验证消息关联、参数校验、停止条件和客户端请求。"""

    def run_with_responses(self, responses, max_steps=5):
        """保存每轮请求快照，避免历史列表后续追加影响断言。"""
        snapshots = []
        responses = iter(responses)

        def generate(messages, tools):
            """记录实际传给模型的消息和工具声明。"""
            snapshots.append((deepcopy(messages), tools))
            return next(responses)

        with patch.object(agent.llm, "generate", side_effect=generate), patch("builtins.print"):
            result = agent.run_agent("查询北京天气并推荐景点", max_steps=max_steps)
        return result, snapshots

    def test_weather_then_attraction(self):
        """天气和景点结果按调用 ID 回传，第三轮直接返回最终答复。"""
        weather = Mock(return_value="北京晴，20℃")
        attraction = Mock(return_value="推荐颐和园")
        with patch.dict(agent.available_tools, {"get_weather": weather, "get_attraction": attraction}, clear=True):
            result, snapshots = self.run_with_responses([
                tool_message(("weather-1", "get_weather", '{"city":"北京"}')),
                tool_message(("attraction-1", "get_attraction", '{"city":"北京","weather":"北京晴，20℃"}')),
                ChatCompletionMessage(role="assistant", content="今天适合游览颐和园。"),
            ])
        self.assertEqual(result, "今天适合游览颐和园。")
        weather.assert_called_once_with(city="北京")
        attraction.assert_called_once_with(city="北京", weather="北京晴，20℃")
        self.assertEqual([message["role"] for message in snapshots[2][0]], ["system", "user", "assistant", "tool", "assistant", "tool"])
        self.assertEqual(snapshots[1][0][-1], {"role": "tool", "tool_call_id": "weather-1", "content": "北京晴，20℃"})
        self.assertEqual(snapshots[2][0][-1]["tool_call_id"], "attraction-1")
        self.assertTrue(all(tools == agent.TOOLS for _, tools in snapshots))

    def test_multiple_calls_and_invalid_arguments(self):
        """同轮多个调用均有结果；非法参数和未知工具不会执行真实函数。"""
        cases = [
            ("bad-json", "get_weather", "{"),
            ("not-object", "get_weather", "[]"),
            ("missing", "get_weather", "{}"),
            ("extra", "get_weather", '{"city":"北京","extra":"x"}'),
            ("wrong-type", "get_weather", '{"city":123}'),
            ("unknown", "unknown_tool", "{}"),
        ]
        weather = Mock(return_value="晴")
        with patch.dict(agent.available_tools, {"get_weather": weather}, clear=True):
            _, snapshots = self.run_with_responses([
                tool_message(*cases, ("valid", "get_weather", '{"city":"北京"}')),
                ChatCompletionMessage(role="assistant", content="已处理"),
            ])
        results = snapshots[1][0][3:]
        self.assertEqual([item["tool_call_id"] for item in results], [case[0] for case in cases] + ["valid"])
        self.assertTrue(all(item["content"].startswith("错误:") for item in results[:-1]))
        self.assertEqual(results[-1]["content"], "晴")
        weather.assert_called_once_with(city="北京")

    def test_tool_failure_and_step_limit(self):
        """工具异常会回传给模型，持续调用工具时仍受最大轮数限制。"""
        call = tool_message(("weather-1", "get_weather", '{"city":"北京"}'))
        with patch.dict(agent.available_tools, {"get_weather": Mock(side_effect=RuntimeError("天气服务不可用"))}, clear=True):
            result, snapshots = self.run_with_responses([call, call], max_steps=2)
        self.assertIn("天气服务不可用", snapshots[1][0][-1]["content"])
        self.assertIn("最大循环次数", result)
        self.assertEqual(len(snapshots), 2)

    def test_client_preserves_tool_calls_and_reports_api_failure(self):
        """客户端发送 tools 并返回完整消息，API 异常使任务及时结束。"""
        message = tool_message(("weather-1", "get_weather", '{"city":"北京"}'))
        messages = [{"role": "user", "content": "北京天气"}]
        with patch.object(agent.llm.client.chat.completions, "create") as create, patch("builtins.print"):
            create.return_value.choices = [Mock(message=message)]
            self.assertIs(agent.llm.generate(messages, agent.TOOLS), message)
            create.assert_called_once_with(model=agent.MODEL_ID, messages=messages, tools=agent.TOOLS, stream=False)
            create.reset_mock()
            create.side_effect = RuntimeError("模型服务不可用")
            self.assertIn("模型服务不可用", agent.run_agent("北京天气"))
            create.assert_called_once()


